var r=80;var a=`080-reverse-searing`;var i=`070`;var o={en:`Reverse Searing`,ua:`Метод зворотного обсмажування`};var n={short:`Reverse searing cooks a thick cut gently first and creates a browned crust at the end. It helps control the difference between surface and center temperature.`,sections:[{title:`Core idea`,text:`Traditional searing often begins with high surface heat. Reverse searing inverts that order: low oven heat slowly raises the center temperature, after which a short hot-pan or grill finish makes the crust. Surface drying during the first stage can support faster browning later.`},{title:`Scientific / practical principles`,text:`Gentler temperature gradients reduce the contrast between an overcooked outer band and the center. Because the finishing sear adds heat, the first stage should stop below the intended final temperature by an amount determined by thickness, cooking method, and recipe. The technique does not automatically guarantee safe pasteurization.`},{title:`How to apply it`,text:`Choose a thick, fairly uniform cut. Put it on a rack in a low oven, monitor the center with a probe, and follow a validated time-temperature plan for the specific meat and audience. Remove it below the planned finish temperature, dry the surface if needed, then sear briefly on a suitably hot pan or grill. Recheck final internal temperature before service.`},{title:`Practical example`,text:`For a thick beef steak, gently heat it in a low oven using a probe, then brown its surface briefly in a hot skillet. Track the temperature before and after the sear rather than copying the timing from a thinner steak. The reference recipe’s temperature is a culinary example, not a universal safe endpoint.`},{title:`Common mistakes and limitations`,text:`This method is poorly suited to very thin cuts, which can overcook during the final sear. Do not use low oven temperature without monitoring food safety or assume that browning kills pathogens throughout a piece. Cooking endpoint requirements depend on meat type, processing, and who will eat it.`},{title:`Best use`,text:`For a thick steak or roast, cook in a moderate oven with a thermometer and finish briefly in a very hot pan or over direct grill heat. Allow for final temperature rise during searing. Follow appropriate food-safety recommendations for the particular meat and do not use this low-temperature approach to store partially cooked food for later.`},{title:`Related theories`,text:`050, 070, 072, 077.`}]};var s={short:`Зворотне обсмажування спочатку м’яко прогріває товстий шматок, а наприкінці створює рум’яну скоринку. Метод допомагає контролювати різницю температур між поверхнею й центром.`,sections:[{title:`Суть`,text:`Звичайна техніка часто починається з обсмажування поверхні, а reverse sear змінює порядок: слабкий жар духовки поступово прогріває середину, після чого коротке обсмажування створює скоринку. Під час першого етапу поверхня частково підсихає, що допомагає наступному підрум’яненню.`},{title:`Наукові та практичні принципи`,text:`Пологіший температурний градієнт зменшує товщину пересмаженого шару біля поверхні. Оскільки завершальне обсмажування додасть тепла, перший етап слід закінчити нижче бажаної фінальної температури, з урахуванням товщини й рецепта. Сам метод не гарантує безпечної пастеризації.`},{title:`Як застосовувати`,text:`Оберіть товстий рівномірний шматок. Покладіть на решітку в духовці з невисокою температурою, стежте за центром термощупом і дотримуйтеся перевіреного температурно-часового режиму для відповідного м’яса та споживачів. Зупиніть перший етап раніше кінцевої температури, за потреби обсушіть поверхню й коротко обсмажте на гарячій сковороді або грилі. Перед подачею перевірте кінцеву температуру.`},{title:`Практичний приклад`,text:`Товстий яловичий стейк можна повільно прогріти в духовці за показами термощупа, а потім швидко обсмажити на сковороді. Порівняйте температуру до й після скоринки, замість сліпо повторювати час для тонкого стейка. Температура з авторського рецепта є кулінарним прикладом, а не універсальною нормою безпечності.`},{title:`Поширені помилки й обмеження`,text:`Для тонких шматків метод мало придатний: фінальне обсмажування легко перегріває середину. Не використовуйте низьку температуру без контролю часу та безпечності й не думайте, що скоринка знищує небезпечні мікроорганізми в усьому шматку. Вимоги залежать від виду та обробки м’яса й людей, для яких його готують.`},{title:`Коли застосовувати`,text:`Товстий стейк чи ростбіф спочатку готуйте в помірній духовці з термометром, а потім коротко обсмажте на дуже гарячій сковороді або грилі. Враховуйте підвищення температури під час завершального обсмажування. Дотримуйтеся вимог безпечності для конкретного виду м’яса й не залишайте частково приготовлений продукт на зберігання.`},{title:`Пов’язані теорії`,text:`050, 070, 072, 077.`}]};var l=[50,70,72,77];var h=`References / Джерела`;var c=[`https://annex.exploratorium.edu/cooking/icooks/2-1-03article.html`,`https://altonbrown.com/recipes/reverse-sear-ribeye-steak/`,`https://extension.umn.edu/food/preparing/cooking-at-home`,`https://ask.fsis.usda.gov/article/Is-it-safe-to-partially-cook-meat-or-poultry-and-finish-it-later`];var d={id:80,slug:a,group:`070`,title:o,en:n,ua:s,related:l,referenceTitle:h,references:c};export{d as default,n as en,i as group,r as id,h as referenceTitle,c as references,l as related,a as slug,o as title,s as ua};